/**
 * Feature `config-change` (Phase 6 slice 6f, builder A, GMP): configuration change control (contract ns/config.ts;
 * kernel 1195; DI-09) and the review-by-exception rules (recipe-core 1050; DI-26, PR-52).
 *
 * The database decides: a configuration row is written only under an approved, open change record that covers its area
 * (EBMR-CFG-001 to -004); this feature puts the request's change-record number into the command's actor context
 * (ActorContext.changeRecord) and runs each write as the person's own command. The approval of a change record is the
 * signable action CONFIG_CHANGE_ACT (signables.ts).
 */
import { routes, type PlatformSettingView, type RbeRuleView } from '@ebmr/api-contract';
import { config as kernelConfig, type commands } from '@ebmr/kernel';
import type { FastifyInstance } from 'fastify';
import type { AppContext } from '../../platform/context.ts';
import { withIdempotentActorCommand } from '../../platform/db/commands.ts';
import { bindRoutes } from '../../platform/http/bind.ts';
import { refusal } from '../../platform/http/refusal.ts';
import type { SignableActionRegistry } from '../../platform/ports.ts';
import { CONFIG_GUIDANCE } from './guidance.ts';
import { changeRecordViews, platformSettingViews, rbeRuleViews } from './reads.ts';
import { configChangeActHandler } from './signables.ts';

type JsonValue = commands.JsonValue;

export const guidance = CONFIG_GUIDANCE;

export function registerSignableActions(registry: SignableActionRegistry, app: AppContext): void {
  if (app.installation !== 'GMP') return;
  registry.register(configChangeActHandler(app));
}

const notFound = (what: string) =>
  refusal(404, { code: 'EBMR-CFG-002', kind: 'INVALID_INPUT', whatHappened: `${what} was not found.`, why: 'There is no such record.', whatYouCanDo: ['Reload the list.'] });

export function plugin(scope: FastifyInstance, app: AppContext): Promise<void> {
  const pool = app.pools.app;
  const recordView = async (num: string) => {
    const [v] = await changeRecordViews(app, pool, { number: num });
    if (!v) throw notFound(`Change record ${num}`);
    return v;
  };
  bindRoutes(scope, app, routes.config, {
    areas: async ({ requireSession }) => {
      requireSession();
      const areas = await kernelConfig.listConfigAreas(pool);
      return { areas };
    },
    changeRecords: async ({ query, requireSession }) => {
      requireSession();
      return { changeRecords: await changeRecordViews(app, pool, query.state !== undefined ? { state: query.state } : {}) };
    },
    raiseChangeRecord: async ({ body, actor, idempotencyKey, requestHash }) => {
      const { attribution: _a, ...def } = body;
      void _a;
      await withIdempotentActorCommand(pool, actor(), idempotencyKey ?? '', requestHash, async (c) => (await kernelConfig.raiseChangeRecord(c, def)) as JsonValue);
      return recordView(def.number);
    },
    closeChangeRecord: async ({ params, body, actor, idempotencyKey, requestHash }) => {
      await withIdempotentActorCommand(pool, actor(), idempotencyKey ?? '', requestHash, async (c) => {
        await kernelConfig.closeChangeRecord(c, params.number, body.note);
        return params.number;
      });
      return recordView(params.number);
    },
    asOf: async ({ query, requireSession }) => {
      requireSession();
      const items = await kernelConfig.configurationAsOf(pool, query.at, query.area);
      return { at: query.at, items: items.map((i) => ({ area: i.area, itemKey: i.itemKey, value: i.value as Record<string, unknown>, validFrom: i.validFrom, basis: i.basis, changeRecord: i.changeRecord })) };
    },
    diff: async ({ query, requireSession }) => {
      requireSession();
      const d = await kernelConfig.configurationDiff(pool, query.from, query.to, query.area);
      return {
        from: query.from,
        to: query.to,
        differences: d.map((x) => ({ ...x, before: x.before as Record<string, unknown> | null, after: x.after as Record<string, unknown> | null })),
      };
    },
    settings: async ({ requireSession }) => {
      requireSession();
      return { settings: await platformSettingViews(pool) };
    },
    setSetting: async ({ params, body, actor, idempotencyKey, requestHash }): Promise<PlatformSettingView> => {
      const ctx = { ...actor({ reasonCode: 'CONFIG_CHANGE', reasonText: body.reason }), changeRecord: body.changeRecord };
      await withIdempotentActorCommand(pool, ctx, idempotencyKey ?? '', requestHash, async (c) => kernelConfig.setPlatformSetting(c, params.key, body.value));
      const [v] = await platformSettingViews(pool, params.key);
      if (!v) throw notFound(`Setting ${params.key}`);
      return v;
    },
    rbeRules: async ({ query, requireSession }) => {
      requireSession();
      return { rules: await rbeRuleViews(pool, query.at) };
    },
    setRbeRule: async ({ params, body, actor, idempotencyKey, requestHash }): Promise<RbeRuleView> => {
      const ctx = { ...actor({ reasonCode: 'RBE_RULE_CHANGE', reasonText: body.rationale }), changeRecord: body.changeRecord };
      await withIdempotentActorCommand(pool, ctx, idempotencyKey ?? '', requestHash, async (c) => {
        const { rows } = await c.query<{ id: string }>('select recipe.set_rbe_rule($1, $2, $3, $4)::text as id', [params.category, body.included, body.minSeverity, body.rationale]);
        return rows[0]?.id ?? null;
      });
      const [v] = await rbeRuleViews(pool, undefined, params.category);
      if (!v) throw notFound(`Review category ${params.category}`);
      return v;
    },
  });
  return Promise.resolve();
}

/**
 * Guidance for the configuration change-control codes (kernel 1195) and the RBE rule codes (recipe-core 1050); Phase 6
 * slice 6f, builder A.
 */
import type { GuidanceEntry } from '../../platform/http/guidance.ts';

export const CONFIG_GUIDANCE: Readonly<Record<string, GuidanceEntry>> = {
  'EBMR-CFG-*': {
    status: 422,
    kind: 'NOT_ALLOWED',
    whatHappened: 'Configuration change control refused this.',
    whatYouCanDo: ['Read the reason below; the change record page shows its state and the areas it covers.'],
    whoCanHelp: ['QA (change control)'],
    controls: ['DI-09'],
  },
  'EBMR-CFG-001': {
    status: 422,
    kind: 'NOT_ALLOWED',
    whatHappened: 'A configuration change needs a change-record id; this one named none.',
    whatYouCanDo: ['Raise a change record for the change, have QA approve it, then make the change under its number.'],
    whoCanHelp: ['QA (change control)'],
    controls: ['DI-09'],
  },
  'EBMR-CFG-002': {
    status: 404,
    kind: 'INVALID_INPUT',
    whatHappened: 'There is no change record with this number.',
    whatYouCanDo: ['Check the number on the change records page.'],
    whoCanHelp: ['QA (change control)'],
    controls: ['DI-09'],
  },
  'EBMR-CFG-003': {
    status: 409,
    kind: 'NOT_ALLOWED',
    whatHappened: 'The change record is not approved yet, or it is closed.',
    whatYouCanDo: ['Have QA approve the change record, or raise a new one if it is closed.'],
    whoCanHelp: ['QA (change control)'],
    controls: ['DI-09'],
  },
  'EBMR-CFG-004': {
    status: 409,
    kind: 'NOT_ALLOWED',
    whatHappened: 'The change record does not cover this configuration area.',
    whatYouCanDo: ['Use a change record that names this area, or raise one.'],
    whoCanHelp: ['QA (change control)'],
    controls: ['DI-09'],
  },
  'EBMR-RBE-*': {
    status: 422,
    kind: 'NOT_ALLOWED',
    whatHappened: 'The review-by-exception rule was refused.',
    whatYouCanDo: ['Read the reason below. A mandatory review category always stays on the review; a rule can only raise its severity.'],
    whoCanHelp: ['QA'],
    controls: ['DI-26', 'PR-52'],
  },
};

/**
 * The quality unit's approval of a configuration change record (Phase 6 slice 6f, builder A; signable action
 * CONFIG_CHANGE_ACT). It signs the change record the database act works on and records the approval with that signature
 * in the same transaction; the database decides (kernel 1195: the record is OPEN, the signer records their own
 * signature, the raiser never approves) and a refusal signs nothing (esig/db-acts.ts).
 *
 *   CONFIG_CHANGE_ACT APPROVE   config_change_record <number>   CONFIG_CHANGE_APPROVED (QA), state OPEN   platform.approve_change_record
 */
import type { SignableAction } from '@ebmr/api-contract';
import type { AppContext } from '../../platform/context.ts';
import type { SignableActionHandler } from '../../platform/ports.ts';
import { dbActHandler } from '../esig/db-acts.ts';

type ConfigChangeAct = Extract<SignableAction, { kind: 'CONFIG_CHANGE_ACT' }>;

export function configChangeActHandler(app: AppContext): SignableActionHandler<ConfigChangeAct> {
  return dbActHandler<ConfigChangeAct>(app, {
    kind: 'CONFIG_CHANGE_ACT',
    aggregateTypes: ['config_change_record'],
    target: (a) => ({ aggregateType: 'config_change_record', aggregateId: a.number, meaning: 'CONFIG_CHANGE_APPROVED', expectedState: 'OPEN' }),
    async apply(client, _ctx, a, signatureId) {
      await client.query('select platform.approve_change_record($1, $2)', [a.number, signatureId]);
      return { act: a.act, number: a.number };
    },
  });
}

/**
 * Reads of the configuration change control (Phase 6 slice 6f, builder A; kernel 1195, recipe-core 1050): change records
 * with their state, the configuration of an instant and the difference between two, platform settings and RBE rules.
 */
import type { ChangeRecordView, PlatformSettingView, RbeRuleView } from '@ebmr/api-contract';
import type pg from 'pg';
import type { AppContext } from '../../platform/context.ts';
import { peopleOf, personRef, usOf } from '../common/people.ts';

type Db = Pick<pg.Pool, 'query'>;

interface RecordRow {
  id: string;
  number: string;
  title: string;
  description: string;
  areas: string[];
  state: ChangeRecordView['state'];
  raised_by: string;
  raised_us: string;
  approved_by: string | null;
  approved_us: string | null;
  closed_us: string | null;
}

export async function changeRecordViews(app: AppContext, db: Db, filter: { number?: string; state?: string }): Promise<ChangeRecordView[]> {
  const { rows } = await db.query<RecordRow>(
    `select c.id, c.number, c.title, c.description, c.areas, platform.change_record_state(c.id) as state,
            c.raised_by_person::text as raised_by, ${usOf('c.raised_at')} as raised_us,
            a.person_id::text as approved_by, case when a.id is null then null else ${usOf('a.recorded_at')} end as approved_us,
            case when x.id is null then null else ${usOf('x.recorded_at')} end as closed_us
       from platform.change_record c
       left join platform.change_record_event a on a.change_record_id = c.id and a.event = 'APPROVED'
       left join platform.change_record_event x on x.change_record_id = c.id and x.event = 'CLOSED'
      where ($1::text is null or c.number = $1) and ($2::text is null or platform.change_record_state(c.id) = $2)
      order by c.raised_at desc, c.number
      limit 500`,
    [filter.number ?? null, filter.state ?? null],
  );
  const people = await peopleOf(db, rows.flatMap((r) => [r.raised_by, r.approved_by]));
  return rows.map((r) => ({
    changeRecordId: r.id,
    number: r.number,
    title: r.title,
    description: r.description,
    areas: r.areas,
    state: r.state,
    raisedBy: personRef(people, r.raised_by, ''),
    raisedAt: app.formatInstant(r.raised_us),
    approvedBy: r.approved_by === null ? null : personRef(people, r.approved_by, ''),
    approvedAt: r.approved_us === null ? null : app.formatInstant(r.approved_us),
    closedAt: r.closed_us === null ? null : app.formatInstant(r.closed_us),
    signable: { aggregateType: 'config_change_record', aggregateId: r.number, meaning: 'CONFIG_CHANGE_APPROVED', expectedState: 'OPEN' },
  }));
}

export async function platformSettingViews(db: Db, key?: string): Promise<PlatformSettingView[]> {
  const { rows } = await db.query<{
    key: string; value: string; default_value: string; value_type: PlatformSettingView['valueType']; allowed_values: string[] | null;
    min_value: string | null; max_value: string | null; unit: string | null; description: string; basis: string;
  }>(
    `select d.key, platform.setting_text(d.key) as value, d.default_value, d.value_type, d.allowed_values, d.min_value::text, d.max_value::text,
            d.unit, d.description, d.basis
       from platform.setting_definition d where $1::text is null or d.key = $1 order by d.key`,
    [key ?? null],
  );
  return rows.map((r) => ({
    key: r.key, value: r.value, defaultValue: r.default_value, valueType: r.value_type, allowedValues: r.allowed_values,
    minValue: r.min_value, maxValue: r.max_value, unit: r.unit, description: r.description, basis: r.basis,
  }));
}

export async function rbeRuleViews(db: Db, at?: string, category?: string): Promise<RbeRuleView[]> {
  const { rows } = await db.query<{
    category: string; mandatory: boolean; included: boolean; min_severity: RbeRuleView['minSeverity']; version: number | null; rationale: string | null; valid_from: string | null;
  }>(
    `select category, mandatory, included, min_severity, version, rationale,
            to_char(valid_from at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') as valid_from
       from recipe.rbe_rules_as_of(coalesce($1::timestamptz, clock_timestamp())) where $2::text is null or category = $2`,
    [at ?? null, category ?? null],
  );
  return rows.map((r) => ({
    category: r.category, mandatory: r.mandatory, included: r.included, minSeverity: r.min_severity, version: r.version, rationale: r.rationale, validFrom: r.valid_from,
  }));
}

